tle":"3. Ground Transport & Jewel Changi Access","audience":"all"}],"summary":"Arrival procedures, electronic SG Arrival Card verification, and Jewel access."},"lounges":[{"name":"SilverKris Lounge","amenities":["shower_suites","fine_dining_buffet","barista_coffee","private_nap_pods","fast_wifi"],"source_url":"https://singaporeair.com","affiliate_url":null,"location_type":"airside","access_summary":"Singapore Airlines and Star Alliance First & Business Class passengers","estimated_price":null,"last_verified_at":"2026-09-01","location_summary":"Terminal 2 and Terminal 3 Airside, 3rd Floor","operating_hours_summary":"24 hours daily"},{"name":"SATS Premier Lounge","amenities":["buffet","showers","massage_chairs","workstations"],"source_url":null,"affiliate_url":null,"location_type":"airside","access_summary":"Priority Pass, DragonPass, LoungeKey, and walk-in pass","estimated_price":{"max":55,"min":45,"currency":"SGD"},"last_verified_at":"2026-09-01","location_summary":"Airside Terminals 1, 2, and 3","operating_hours_summary":"24 hours daily"}],"notices":[{"body":"All foreign travelers must submit the official SG Arrival Card online via ICA Singapore website or MyICA mobile app within 3 days prior to landing.","title":"Mandatory SG Arrival Card (SGAC)"}],"departure":{"steps":[{"body":"Passengers flying on participating airlines can check in and drop luggage at the Jewel Early Check-in Lounge up to 24 hours prior to scheduled departure.","title":"1. Early Check-in at Jewel Lounge","audience":"all"},{"body":"Departure passport control uses automated facial recognition gates. Terminal concourses feature butterfly gardens, rooftop pools, and transit lounges.","title":"2. Centralized Automated Immigration","audience":"all"},{"body":"Important note: In Terminals 1, 2, and 3, security screening takes place directly at the individual boarding gate. Arrive at your gate at least 45 minutes before departure.","title":"3. Gate-Level Security Screening","audience":"all"}],"summary":