4) or app ride bays"}],"facilities":[{"name":"Jewel Changi Rain Vortex","summary":"World's tallest indoor waterfall (40m) surrounded by a four-story lush indoor forest canopy.","category":"Leisure"},{"name":"High-Speed WiFi & Power Stations","summary":"Free high-speed WiFi (#WiFi@Changi) and over 1,500 USB/AC charging stations throughout all terminals.","category":"Connectivity"},{"name":"Complimentary Singapore City Tour","summary":"Free 2.5-hour guided city tours available for transit passengers with layovers of 5.5 hours or more.","category":"Transit"}],"orientation":{"intro":"Singapore Changi Airport (SIN) consistently ranks among the world's finest airports, located 20 km east of downtown Singapore.","summary":"With four world-class passenger terminals and the Jewel lifestyle complex, Changi serves over 65 million travelers annually with seamless inter-terminal transit.","terminal_count":4,"city_distance_km":20},"quick_answers":{"terminal_count":4,"city_distance_km":20,"default_transport":{"name":"MRT East-West Line / Grab Taxi","estimated_price":{"max":35,"min":2,"currency":"SGD"},"typical_minutes":{"max":45,"min":25}}},"internal_link_groups":[{"links":[{"path":"/flights-from/singapore","anchor_text":"Flights from Singapore"}],"cluster":"city"},{"links":[{"path":"/flights/singapore-to-london","anchor_text":"Flights to London (LHR/LGW)"},{"path":"/flights/hanoi-to-singapore","anchor_text":"Flights to Hanoi (HAN)"}],"cluster":"routes"}]}$AIRPORT_singapore_changi_airport$::jsonb,
